#ifndef VF_DRIVE_H
#define VF_DRIVE_H

#include <foc/hardware.h>
#include <foc/svpwm.h>
#include <foc/encoder.h>

struct open_loop_t {
    // Electrical angle generated by the open-loop controller.
    float angle = 0.0f;
    // Current commanded SVPWM modulation, Vref / Vbus
    float modulation = 0.0f;
    // Current commanded electrical frequency [Hz]
    float electrical_frequency = 0.0f;
    // Open-loop update rate [Hz].
    // Should match the TIM1 update ISR rate.
    float update_frequency = 20'000.0f;   // Hz
    // Ramp configuration
    float modulation_start = 0.2f;
    float modulation_end   = 0.2f;
    // 0.05f ultra slow works but with some jitter
    // 0.1f works with little jitter
    // 0.5f is butter smooth
    float frequency_start = 0.5f;
    float frequency_end   = 0.5f;
    // Ramp duration [s].
    float ramp_duration_s = 30.0f;
};

inline open_loop_t g_open_loop;
inline volatile bool encoder_hold = true;

inline void open_loop_update() {
    float angle = g_open_loop.angle;
    float alpha = g_open_loop.modulation * cosf(angle);
    float beta = g_open_loop.modulation * sinf(angle);
    voltage_to_timer_pwm(&(hw.pwm_timer), alpha, beta);
    // advance the angle based on commanded electrical frequency
    float angle_step = TWO_PI * g_open_loop.electrical_frequency /
        g_open_loop.update_frequency;
    g_open_loop.angle += angle_step;
    if (g_open_loop.angle >= TWO_PI) {
        g_open_loop.angle -= TWO_PI;
    }
}

inline void tim1_callback_open(timer_event_t event) {
    if (!encoder_hold && event == TIMER_EVENT_UPDATE) {
        open_loop_update();
    }
}

inline void tim2_encoder_vfd_callback(timer_event_t event) {
    if (event == TIMER_EVENT_UPDATE) {
        // executes at 1kHz
        encoder.update();
    }
}

inline void test_vf_drive() {
    // TIM1 CH1/2/3 SVPWM setup
    initialize_phase_pwm_timer(tim1_callback_open);

    g_open_loop.angle = 0.0f;
    g_open_loop.modulation = g_open_loop.modulation_start;
    g_open_loop.electrical_frequency = g_open_loop.frequency_start;

    timer_enable_interrupt(&(hw.pwm_timer));
    encoder_hold = true;
    timer_start(&(hw.pwm_timer));

    // Encoder bus
    encoder.calibrate_sign_and_offset();
    // Start velocity estimation from a clean state.
    encoder.reset_velocity();
    // Read the encoder at the final calibrated rotor position.
    encoder.update();
    // Start the open-loop electrical field from the
    // same electrical angle as the encoder.
    // Snapshot read encoder
    const auto& enc = encoder.read();
    g_open_loop.angle = enc.electrical_angle;
    // Encoder TIM2 read setup
    initialize_encoder_timer(tim2_encoder_vfd_callback);

    const uint32_t ramp_start_ms = mcl::time_ms();
    uint32_t last_ramp_update_ms = ramp_start_ms;
    // Now allow TIM1 to advance the open-loop field.
    encoder_hold = false;

    while (true) {
        uint32_t now_ms = mcl::time_ms();
        // 1 ms foreground ramp update
        if ((uint32_t)(now_ms - last_ramp_update_ms) >= 1U) {
            float elapsed_s = (float)(now_ms - ramp_start_ms) * 0.001f;
            // voltage and frequency ramps are synchronized
            // since both use the same elapsed_s
            g_open_loop.modulation =
                ramp_linear(
                    g_open_loop.modulation_start,
                    g_open_loop.modulation_end,
                    g_open_loop.ramp_duration_s,
                    elapsed_s);
            g_open_loop.electrical_frequency =
                ramp_linear(
                    g_open_loop.frequency_start,
                    g_open_loop.frequency_end,
                    g_open_loop.ramp_duration_s,
                    elapsed_s);
            last_ramp_update_ms = now_ms;
        }
        static uint32_t last_log_ms = 0;
        if ((uint32_t)(now_ms - last_log_ms) >= 500U) {
            const auto& enc = encoder.read();
            float phase_error =
                g_open_loop.angle - enc.electrical_angle;
            // wrap phase error to [-PI, PI].
            if (phase_error > PI)
                phase_error -= TWO_PI;
            else if (phase_error < -PI)
                phase_error += TWO_PI;
            LOG << "mod: " << g_open_loop.modulation
                << " cmd_ef: " << g_open_loop.electrical_frequency
                << " cmd_ea: " << g_open_loop.angle
                << " enc_ea: " << enc.electrical_angle
                << " ph_err: " << phase_error
                << " ma: " << enc.mechanical_angle
                << " wm: " << enc.mechanical_velocity
                << " we: " << enc.electrical_velocity;
            last_log_ms = now_ms;
        }
    }
    timer_stop(&(hw.pwm_timer));
}

#endif